function resetTheme(){console.group("🎨 Theme Reset");const e=[];["theme","admin-theme","theme-preference"].forEach(o=>{localStorage.getItem(o)&&(e.push(o+": "+localStorage.getItem(o)),localStorage.removeItem(o))}),e.length>0?(console.log("Removed stale theme values:"),e.forEach(e=>console.log("  -",e))):console.log("No stale theme values found");const o=window.matchMedia("(prefers-color-scheme: dark)").matches?"forest":"lofi";return localStorage.setItem("theme",o),document.documentElement.setAttribute("data-theme",o),console.log("✅ Theme reset to:",o),console.log("🔄 Reload page to see changes"),console.groupEnd(),o}function checkTheme(){console.group("🎨 Theme Status"),console.log("LocalStorage:"),["theme","admin-theme","theme-preference"].forEach(e=>{const o=localStorage.getItem(e);if(o){const t="lofi"===o||"forest"===o;console.log(`  ${e}: "${o}" ${t?"✅":"❌ INVALID"}`)}});const e=document.documentElement.getAttribute("data-theme");console.log("\nCurrent document theme:",e);const o=window.matchMedia("(prefers-color-scheme: dark)").matches;console.log("System preference:",o?"dark (forest)":"light (lofi)"),console.log("\nValid themes:"),console.log("  - lofi (light theme)"),console.log("  - forest (dark theme)"),console.groupEnd()}window.resetTheme=resetTheme,window.checkTheme=checkTheme,console.info("🎨 Theme utilities loaded. Run checkTheme() or resetTheme() in console if needed.");